private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    } else {
        // node is the head
        head = next;
    }

    if (next != null) {
        next.prev = prev;
    } else {
        // node is the tail
        tail = prev;
    }

    node.next = null;
    node.prev = null;
    size--;

    return true;
}

